const expand = 'Orders($select=OrderID,OrderDate;$expand=Order_Details($select=UnitPrice,Quantity,Discount;$expand=Product($select=ProductName)))';
const url = 'https://services.odata.org/V4/Northwind/Northwind.svc/Customers?$format=json&$select=CustomerID,CompanyName,City,Country&$expand=' + encodeURIComponent(expand);
return [{ json: { url, hoje: '1998-05-06' } }];

const hoje = $('Monta consulta').first().json.hoje;
const paginas = $input.all();
const clientes = paginas.flatMap(p => p.json.value || []).map(c => {
  const produtos = {};
  const pedidos = (c.Orders || []).map(o => {
    let valor = 0;
    for (const d of o.Order_Details || []) {
      const liquido = d.UnitPrice * d.Quantity * (1 - d.Discount);
      valor += liquido;
      produtos[d.Product.ProductName] = (produtos[d.Product.ProductName] || 0) + liquido;
    }
    return { pedido: o.OrderID, data: o.OrderDate.slice(0, 10), valor };
  }).sort((a, b) => a.data.localeCompare(b.data));
  return { id: c.CustomerID, nome: c.CompanyName, cidade: c.City, pais: c.Country, pedidos, produtos };
});
return [{ json: { hoje, paginas: paginas.length, clientes } }];

const d = $('Normaliza clientes').first().json;
const inicio = query.inicio || '1996-01-01';
const fim = query.fim || d.hoje;
const r2 = v => Math.round(v * 100) / 100;
const ativos = d.clientes.map(c => {
  const lista = c.pedidos.filter(p => p.data >= inicio && p.data <= fim);
  return { nome: c.nome, pais: c.pais, pedidos: lista.length, valor: lista.reduce((s, p) => s + p.valor, 0), novo: c.pedidos.length > 0 && c.pedidos[0].data >= inicio && c.pedidos[0].data <= fim };
}).filter(c => c.pedidos > 0).sort((a, b) => b.valor - a.valor);
if (!ativos.length) return JSON.stringify({ status: 'SEM_DADOS', inicio, fim });
const total = ativos.reduce((s, c) => s + c.valor, 0);
const cinco = ativos.slice(0, 5);
const somaCinco = cinco.reduce((s, c) => s + c.valor, 0);
return JSON.stringify({ status: 'OK', inicio, fim, clientes_cadastrados: d.clientes.length, clientes_com_compra: ativos.length, novos: ativos.filter(c => c.novo).length, recorrentes: ativos.filter(c => !c.novo).length, faturamento: r2(total), faturamento_medio_por_cliente: r2(total / ativos.length), concentracao_cinco_maiores_pct: r2(somaCinco / total * 100), cinco_maiores: cinco.map(c => ({ nome: c.nome, pais: c.pais, pedidos: c.pedidos, faturamento: r2(c.valor) })) });

const d = $('Normaliza clientes').first().json;
const r2 = v => Math.round(v * 100) / 100;
const corte = Number(query.dias) || 90;
const diasEntre = (a, b) => Math.round((Date.parse(b) - Date.parse(a)) / 86400000);
const nunca = d.clientes.filter(c => !c.pedidos.length).map(c => c.nome);
const parados = d.clientes.filter(c => c.pedidos.length).map(c => {
  const ultima = c.pedidos[c.pedidos.length - 1].data;
  return { nome: c.nome, pais: c.pais, ultima_compra: ultima, dias_sem_comprar: diasEntre(ultima, d.hoje), pedidos: c.pedidos.length, historico: c.pedidos.reduce((s, p) => s + p.valor, 0) };
}).filter(c => c.dias_sem_comprar > corte).sort((a, b) => b.historico - a.historico);
if (!parados.length && !nunca.length) return JSON.stringify({ status: 'SEM_DADOS', dias: corte });
const limite = Math.min(Number(query.limite) || 10, 30);
return JSON.stringify({ status: 'OK', data_referencia: d.hoje, dias: corte, inativos: parados.length, historico_inativos: r2(parados.reduce((s, c) => s + c.historico, 0)), nunca_compraram: nunca, listados: Math.min(limite, parados.length), clientes: parados.slice(0, limite).map(c => ({ ...c, historico: r2(c.historico) })) });

const d = $('Normaliza clientes').first().json;
const limpa = s => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const termo = limpa(query.nome).trim();
if (!termo) return JSON.stringify({ status: 'PARAMETRO_INVALIDO', campo: 'nome' });
const achados = d.clientes.filter(c => limpa(c.id) === termo || limpa(c.nome).includes(termo));
if (!achados.length) return JSON.stringify({ status: 'NAO_ENCONTRADO', nome: query.nome });
if (achados.length > 1) return JSON.stringify({ status: 'MAIS_DE_UM', opcoes: achados.slice(0, 10).map(c => c.nome) });
const c = achados[0];
const r2 = v => Math.round(v * 100) / 100;
const diasEntre = (a, b) => Math.round((Date.parse(b) - Date.parse(a)) / 86400000);
const base = { status: 'OK', cliente: c.nome, codigo: c.id, cidade: c.cidade, pais: c.pais, pedidos: c.pedidos.length };
if (!c.pedidos.length) return JSON.stringify({ ...base, faturamento: 0 });
const total = c.pedidos.reduce((s, p) => s + p.valor, 0);
const primeira = c.pedidos[0].data;
const ultima = c.pedidos[c.pedidos.length - 1].data;
const produtos = Object.entries(c.produtos).sort((a, b) => b[1] - a[1]).slice(0, 3).map(([nome, valor]) => ({ nome, faturamento: r2(valor) }));
return JSON.stringify({ ...base, faturamento: r2(total), ticket_medio: r2(total / c.pedidos.length), primeira_compra: primeira, ultima_compra: ultima, dias_sem_comprar: diasEntre(ultima, d.hoje), intervalo_medio_dias: c.pedidos.length > 1 ? r2(diasEntre(primeira, ultima) / (c.pedidos.length - 1)) : null, produtos_mais_comprados: produtos });
